      "marking": "arrow:left",
      "evidence": "full"
    },
    {
      "observation": "The word ONLY is painted in white in the lane.",
      "marking": "text:only",
      "evidence": "full"
    },
    {
      "observation": "A solid white line extends across the lane at the intersection.",
      "marking": "line:stop_line",
      "evidence": "full"
    }
  ],
  "cross_check": {
    "position": "The lane count of 1 and index 1 are consistent with the left boundary being an edge line and the right boundary being a lane line (indicating another lane exists to the right).",
    "roles": "The white color and solid pattern for both boundaries fit the roles of edge line and lane line on a city street approach.",
    "markings": "The left-turn arrow and ONLY text are consistent with each other, indicating a mandatory turn lane.",
    "unseen": "No attributes were reported without being visible.",
    "result": "consistent"
  },
  "element_rules": [
    {
      "element": "left_boundary",
      "rule_id": "US-3B.09-01-02",
      "meaning": "The solid white line delineates the left edge of the roadway."
    },
    {
      "element": "right_boundary",
      "rule_id": "US-3B.06-05-06",
      "meaning": "The solid white lane line discourages crossing into the adjacent lane."
    },
    {
      "element": "arrow:left",
      "rule_id": "US-3B.23-01",
      "meaning": "The arrow indicates that a left turn is a permissible or mandatory movement."
    },
    {
      "element": "text:only",
      "rule_id": "US-3B.21-04",
      "meaning": "The ONLY marking supplements the arrow to designate the lane for the exclusive use of a single movement (left turn)."
    },
    {
      "element": "line:stop_line",
      "rule_id": "US-3B.19-01-02",
      "meaning": "The stop line indicates the point where vehicles are required to stop in compliance with a traffic control device."
    }
  ],
  "action_reasons": {
    "change_left": "prohibited by the solid white edge line (US-3B.09-01-02).",
    "change_right": "discouraged by the solid white lane line (US-3B.06-05-06).",
    "go_straight": "prohibited by the mandatory left-turn arrow and ONLY text (US-3B.21-04).",
    "turn_left": "allowed by the left-turn arrow (US-3B.23-01) and ONLY text (US-3B.21-04), but must stop first at the stop line (US-3B.19-01-02).",
    "turn_right": "prohibited by the mandatory left-turn arrow and ONLY text (US-3B.21-04).",
    "u_turn": "prohibited by the mandatory left-turn arrow and ONLY text (US-3B.21-04).",
    "enter_waiting_area": "no marking governs this action"
  },
  "decision_check": "consistent",
  "actions": {
    "change_left": "prohibited",
    "change_right": "prohibited",
    "go_straight": "prohibited",
    "turn_left": "stop_first",
    "turn_right": "prohibited",
    "u_turn": "prohibited",
    "enter_waiting_area": "not_applicable"
  },
  "advice": "You are in a mandatory left-turn lane. You must stop at the stop line and then turn left; do not go straight or change lanes."
}

